#include "helpers/HemisphereLightHelper.h"
#include "geometries/OctahedronGeometry.h"
#include <numbers>
namespace{thread_local Vector3 vector;thread_local Color color1,color2;}
HemisphereLightHelper::HemisphereLightHelper(std::shared_ptr<HemisphereLight> light,double size,HelperColor color):light(std::move(light)),color(std::move(color.value)){if(!this->light)throw JSTypeError("Cannot read properties of undefined (reading 'matrixWorld')");matrix.aliasTo(std::shared_ptr<Matrix4>(this->light,&this->light->matrixWorld),this->light);matrixAutoUpdate=false;type="HemisphereLightHelper";auto geometry=std::make_shared<OctahedronGeometry>(size);geometry->rotateY(std::numbers::pi*.5);material=Helper_detail::meshMaterial();material->wireframe=true;material->fog=false;if(this->color.isUndefined())material->vertexColors=true;auto position=geometry->getAttribute("position");geometry->setAttribute("color",std::make_shared<BufferAttribute>(Float32Array(position->getCount()*3),3));add(std::make_shared<Mesh>(geometry,material));update();}
void HemisphereLightHelper::update(){const auto mesh=Helper_detail::childMesh(*this);if(!color.isUndefined())Helper_detail::setMeshColor(material,color);else{const auto colors=mesh->geometry->getAttribute("color");color1.copy(light->color);color2.copy(light->groundColor);for(double i=0,l=colors->getCount();i<l;++i){const auto& c=i<l/2?color1:color2;colors->setXYZ(i,c.r,c.g,c.b);}colors->setNeedsUpdate(true);}matrixWorldNeedsUpdate=true;{const auto retained=light;if(!retained)throw JSTypeError("light is undefined");retained->updateWorldMatrix(true,false);}mesh->lookAt(vector.setFromMatrixPosition(light->matrixWorld).negate());}
std::shared_ptr<Object3D> HemisphereLightHelper::clone(bool)const{return std::make_shared<HemisphereLightHelper>(nullptr);}
void HemisphereLightHelper::dispose(){Object3D::dispose();Helper_detail::disposeGeometry(Helper_detail::childMesh(*this)->geometry);Helper_detail::disposeMaterial(Helper_detail::childMesh(*this)->material);}
